fn decode_master_box(bytes: &[u8]) -> Result<Box<PoolV1PairForestMasterV1>, ProgramError> {
    assert!(core::mem::size_of::<PoolV1PairForestMasterV1>()==304,"exact Box layout bytes");
    assert!(core::mem::align_of::<PoolV1PairForestMasterV1>()==8,"exact Box layout alignment");
    assert!(!core::mem::needs_drop::<PoolV1PairForestMasterV1>(),"decoded record has no destructor");
    assert!(!core::mem::needs_drop::<aspis_statement::pool_v1::PoolV1PairForestAccountErrorV1>(),"raw decoder error has no destructor");
    let raw=decode_pool_v1_pair_forest_master_v1(bytes);
    let mut allocated: *const PoolV1PairForestMasterV1=core::ptr::null();
    let mut out=(|| {let b=Box::new(raw.map_err(|_| ProgramError::InvalidAccountData)?);allocated=&*b;Ok(b)})();


    match (&raw,&out) {
     (Ok(a),Ok(b))=>{ assert!(core::ptr::eq(&**b,allocated),"same Box allocation");assert!(!core::ptr::eq(&**b,a),"fresh owned carrier");assert!(a.bump==b.bump,"unchanged allocation payload"); },
     (Err(_),Err(e))=>{assert!(*e==ProgramError::InvalidAccountData,"mapped error");assert!(allocated.is_null(),"no allocation on decoder error");},
     _=>assert!(false,"same Result arm")
    }
    out
}
